package org.eclipse.rdf4j.sail.base;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

class SailModelCleanupTest {

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void retainedScopesTransferCleanupToTheFinalReleasingWorkflow() throws Exception {
		TrackingResource resource = new TrackingResource();
		SailModelCleanup.Retained first;
		SailModelCleanup.Retained second;
		try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
			first = SailModelCleanup.retain();
			second = SailModelCleanup.retain();
			SailModelCleanup.defer(resource);
		}
		assertEquals(0, resource.closes.get());

		ExecutorService releaser = Executors.newSingleThreadExecutor();
		try {
			Future<?> firstRelease = releaser.submit(() -> {
				try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
					first.close();
					first.close();
					assertEquals(0, resource.closes.get());
				}
			});
			firstRelease.get(5, TimeUnit.SECONDS);
			first.close();
			assertEquals(0, resource.closes.get());

			Future<?> finalRelease = releaser.submit(() -> {
				try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
					second.close();
					second.close();
					assertEquals(0, resource.closes.get());
				}
			});
			finalRelease.get(5, TimeUnit.SECONDS);
			second.close();
			assertEquals(1, resource.closes.get());
			assertSame(releaserThread(releaser), resource.closedBy.get());
		} finally {
			releaser.shutdownNow();
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void laterOriginWorkflowWaitsForCrossThreadReservationRelease() throws Exception {
		TrackingResource resource = new TrackingResource();
		AtomicReference<SailModelCleanup.Retained> retainedRef = new AtomicReference<>();
		ExecutorService origin = Executors.newSingleThreadExecutor();
		ExecutorService releaser = Executors.newSingleThreadExecutor();
		try {
			Future<?> openReservation = origin.submit(() -> {
				try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
					retainedRef.set(SailModelCleanup.retain());
				}
			});
			openReservation.get(5, TimeUnit.SECONDS);

			Future<?> deferLaterWork = origin.submit(() -> {
				try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
					SailModelCleanup.defer(resource);
				}
				assertEquals(0, resource.closes.get());
			});
			deferLaterWork.get(5, TimeUnit.SECONDS);
			assertEquals(0, resource.closes.get());

			Future<?> release = releaser.submit(() -> {
				try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
					retainedRef.get().close();
					assertEquals(0, resource.closes.get());
				}
			});
			release.get(5, TimeUnit.SECONDS);
			assertEquals(1, resource.closes.get());
			assertSame(releaserThread(releaser), resource.closedBy.get());
		} finally {
			origin.shutdownNow();
			releaser.shutdownNow();
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void retainedReleaseWithoutScopeDoesNotConsumeReservation() {
		TrackingResource resource = new TrackingResource();
		SailModelCleanup.Retained retained;
		try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
			retained = SailModelCleanup.retain();
			SailModelCleanup.defer(resource);
		}

		assertThrows(IllegalStateException.class, retained::close);
		assertEquals(0, resource.closes.get());
		try (SailModelCleanup.Scope ignored = SailModelCleanup.enter()) {
			retained.close();
			assertEquals(0, resource.closes.get());
		}
		retained.close();
		assertEquals(1, resource.closes.get());
	}

	private static Thread releaserThread(ExecutorService executor) throws Exception {
		Future<Thread> thread = executor.submit(Thread::currentThread);
		return thread.get(5, TimeUnit.SECONDS);
	}

	private static final class TrackingResource implements SailClosable {
		private final AtomicInteger closes = new AtomicInteger();
		private final AtomicReference<Thread> closedBy = new AtomicReference<>();

		@Override
		public void close() {
			closedBy.set(Thread.currentThread());
			closes.incrementAndGet();
		}
	}
}
